# Mirrors backend/services/sanitize.py
def normalize(payload: dict) -> dict:
    for lap in payload.get('laps', []):
        lap['tyre_wear_pct'] = max(0, min(100, lap.get('tyre_wear_pct', 0)))
        lap['compound'] = lap.get('compound', 'UNKNOWN').upper()
        if lap.get('lap_time_s', 0) <= 0:
            lap['lap_time_s'] = None
    return payload

def merge(telemetry_ctx: dict, pdf_ctx: dict | None) -> dict:
    merged = {**telemetry_ctx}
    if pdf_ctx and pdf_ctx.get('markdown'):
        merged['pdf_excerpt'] = pdf_ctx['markdown'][:3000]
        merged['pdf_pages'] = pdf_ctx.get('page_count', 0)
    return merged

def decompose(granite_output: dict, telemetry_laps: list) -> dict:
    overall = granite_output.get('confidence', 50)
    lap_quality = sum(1 for l in telemetry_laps if l.get('lap_time_s')) / max(len(telemetry_laps), 1)
    return {
        'data_quality': round(min(100, 50 + lap_quality * 50), 1),
        'model_certainty': overall,
        'stability': 60 if overall >= 62 else 40,
        'regret_bound': round(max(0, min(1, (100 - overall) / 100)), 3)
    }
